वर्ग पंक्तिक्रम पालन मानक.तुलनाकार<पंक्ति> {
    सार्वजनिक फलन तुलना(क: पंक्ति, ख: पंक्ति) -> पूर्णांक {
        यदि (क.कुंजी < ख.कुंजी) { लौटाओ -१; } यदि (क.कुंजी > ख.कुंजी) { लौटाओ १; } लौटाओ ०;
    }
}
सार्वजनिक वर्ग पूर्णांकक्रम पालन तुलनाकार<पूर्णांक> {
    सार्वजनिक फलन तुलना(क: पूर्णांक, ख: पूर्णांक) -> पूर्णांक {
        यदि (क < ख) { लौटाओ -१; } यदि (क > ख) { लौटाओ १; } लौटाओ ०;
    }
}

वर्ग सम पालन चयनक<पूर्णांक> {
    सार्वजनिक फलन चुनो(अ: पूर्णांक) -> तार्किक { लौटाओ अ % २ == ०; }
}
सार्वजनिक साझा फलन छाँटो(मूल: सूची<त>, नियम: चयनक<त>) -> सूची<त> {
    स्थिर फल: सूची<त> = नया सूची<त>();
    प्रत्येक (मूल में व: त) { यदि (नियम.चुनो(व)) { फल.जोड़ो(व); } }
    लौटाओ फल;
}

वर्ग समविषम पालन रूपांतरक<पूर्णांक, पाठ> {
    फलन बदलो(अंक: पूर्णांक) -> पाठ {
        यदि (अंक % २ == ०) { लौटाओ "सम"; }
        लौटाओ "विषम";
